package api

import ("net/http"; "os"; "path/filepath"; "strings"; "github.com/gin-gonic/gin"; "github.com/locallhosts/Wraith/backend-go/linter")
func listRules(s *Server,c *gin.Context){results,err:=linter.LintDir(s.RulesDir);if err!=nil{c.JSON(http.StatusInternalServerError,gin.H{"error":"could not inspect rules: "+err.Error()});return};type summary struct{Name string `json:"name"`;Path string `json:"path"`;Title string `json:"title"`;ID string `json:"id"`;Status string `json:"status"`;Level string `json:"level"`;Passed bool `json:"passed"`;IssueCount int `json:"issue_count"`;ErrorCount int `json:"error_count"`;WarningCount int `json:"warning_count"`};out:=make([]summary,0,len(results));for _,r:=range results{name:=filepath.Base(r.Path);x:=summary{Name:name,Path:r.Path,Passed:r.Passed(),IssueCount:len(r.Issues)};if r.Rule!=nil{x.Title=r.Rule.Title;x.ID=r.Rule.ID;x.Status=r.Rule.Status;x.Level=r.Rule.Level};for _,i:=range r.Issues{switch strings.ToLower(i.Severity){case "error":x.ErrorCount++;case "warning":x.WarningCount++}};out=append(out,x)};c.JSON(http.StatusOK,gin.H{"count":len(out),"rules":out})}
func getRule(s *Server,c *gin.Context){name:=c.Param("name");if name==""||filepath.Base(name)!=name||strings.ContainsAny(name,"/\\\\"){c.JSON(http.StatusBadRequest,gin.H{"error":"invalid rule name"});return};if !strings.HasSuffix(name,".yml")&&!strings.HasSuffix(name,".yaml"){c.JSON(http.StatusBadRequest,gin.H{"error":"rule name must end in .yml or .yaml"});return};path:=filepath.Join(s.RulesDir,name);data,err:=os.ReadFile(path);if err!=nil{if os.IsNotExist(err){c.JSON(http.StatusNotFound,gin.H{"error":"rule not found"});return};c.JSON(http.StatusInternalServerError,gin.H{"error":"could not read rule"});return};result,err:=linter.LintBytes(path,data);if err!=nil{c.JSON(http.StatusInternalServerError,gin.H{"error":"could not lint rule: "+err.Error()});return};c.JSON(http.StatusOK,gin.H{"name":name,"path":path,"passed":result.Passed(),"rule":result.Rule,"issues":result.Issues,"content":string(data)})}
